import sys

def solve():
    """
    This function solves the programming problem.
    It reads the input, processes it, and prints the output.
    """
    try:
        n_str = sys.stdin.readline()
        if not n_str:
            return
        n = int(n_str)
        s = sys.stdin.readline().strip()
    except (IOError, ValueError):
        return

    total_g = s.count('G')

    if total_g == n or total_g == 0:
        print(total_g)
        return

    l_streak = [0] * n
    if s[0] == 'G':
        l_streak[0] = 1
    for i in range(1, n):
        if s[i] == 'G':
            l_streak[i] = l_streak[i - 1] + 1

    r_streak = [0] * n
    if s[n - 1] == 'G':
        r_streak[n - 1] = 1
    for i in range(n - 2, -1, -1):
        if s[i] == 'G':
            r_streak[i] = r_streak[i + 1] + 1

    max_len = 0
    if l_streak:
        max_len = max(l_streak)

    ans = max_len

    for i in range(n):
        if s[i] == 'S':
            left_len = l_streak[i - 1] if i > 0 else 0
            right_len = r_streak[i + 1] if i < n - 1 else 0

            combined = left_len + right_len

            if combined < total_g:
                ans = max(ans, combined + 1)
            else: 
                ans = max(ans, combined)

    print(ans)

