        for c in range(10):
            # Check horizontal
            if c <= 5:
                if all(board[r][c+i] == 'X' for i in range(5)):
                    return True
            # Check vertical
            if r <= 5:
                if all(board[r+i][c] == 'X' for i in range(5)):
