from collections import Counter

def calculate_beauty(ribbon, n):
    l = len(ribbon)
    if l == 0:
        return 0

    counts = Counter(ribbon)
    max_freq = max(counts.values())

    if max_freq == l and n == 1:
        return l - 1

    return min(l, max_freq + n)

