            prev_mask_for_time = mask ^ low_bit
            time_sum[mask] = time_sum[prev_mask_for_time] + time_sum[low_bit]

    for i in range(n):
        dp[1 << i][songs[i][1]] = 1

    for mask in range(1, 1 << n):
        for i in range(n):
            if (mask >> i) & 1:
                prev_mask = mask ^ (1 << i)
                if prev_mask == 0:
                    continue

                g_i = songs[i][1]

                for g_prev in range(1, 4):
                    if g_prev != g_i:
                        dp[mask][g_i] = (dp[mask][g_i] + dp[prev_mask][g_prev]) % MOD

    ans = 0
    for mask in range(1, 1 << n):
        if time_sum[mask] == T:
            total_for_mask = sum(dp[mask]) % MOD
            ans = (ans + total_for_mask) % MOD

    print(ans)

