        for v_move in v_options:
            if v_move == (px_new, py_new):
                continue
            min_tv_after_move = min(min_tv_after_move, max(v_move))

        best_tv_reply = min(min_tv_after_move, max(xv,yv))

        return dp_new <= best_tv_reply

