    def get_count_recursive(y, current_n):
        if y > current_n:
            return 0
        if y in memo:
            return memo[y]

        res = 1

        # Add count from 2*y
        res += get_count_recursive(2 * y, current_n)

        # If y is even, add count from y+1
        if y % 2 == 0:
            res += get_count_recursive(y + 1, current_n)

        memo[y] = res
        return res

    def check(y, target_k):
        if y > n:
            return False
        memo.clear()
        return get_count_recursive(y, n) >= target_k

    ans_odd = 0
    low_idx_odd = 0
    high_idx_odd = (n - 1) // 2

    while low_idx_odd <= high_idx_odd:
        mid_idx = (low_idx_odd + high_idx_odd) // 2
        y = 2 * mid_idx + 1
        if check(y, k):
            ans_odd = y
            low_idx_odd = mid_idx + 1
        else:
            high_idx_odd = mid_idx - 1

