    i = 0
    while i < len(s):
        char = s[i]

        if not ('a' <= char <= 'z'):
            i += 1
            continue

        is_followed_by_special = (i + 1 < len(s) and s[i+1] in ('?', '*'))

        if not is_followed_by_special:
