import sys

def solve():
    """
    Solves the stack-sortable permutation problem.
    """
    try:
        sys.setrecursionlimit(200005)

        n, k = map(int, sys.stdin.readline().split())
        p_prefix = list(map(int, sys.stdin.readline().split()))

        tree = [0] * (4 * (n + 1))

        # Segment tree functions defined inside solve to have access to `tree`
        def build(v, tl, tr, is_used_arr):
            if tl == tr:
                if not is_used_arr[tl]:
                    tree[v] = tl
            else:
                tm = (tl + tr) // 2
                build(v * 2, tl, tm, is_used_arr)
                build(v * 2 + 1, tm + 1, tr, is_used_arr)
                tree[v] = max(tree[v * 2], tree[v * 2 + 1])

        def update(v, tl, tr, pos, new_val):
            if tl == tr:
                tree[v] = new_val
            else:
                tm = (tl + tr) // 2
                if pos <= tm:
                    update(v * 2, tl, tm, pos, new_val)
                else:
                    update(v * 2 + 1, tm + 1, tr, pos, new_val)
                tree[v] = max(tree[v * 2], tree[v * 2 + 1])

        def query(v, tl, tr, l, r):
            if l > r:
                return 0
            if l == tl and r == tr:
                return tree[v]
            tm = (tl + tr) // 2
            left_max = query(v * 2, tl, tm, l, min(r, tm))
            right_max = query(v * 2 + 1, tm + 1, tr, max(l, tm + 1), r)
            return max(left_max, right_max)

        is_used = [False] * (n + 1)
        for x in p_prefix:
            is_used[x] = True

        build(1, 1, n, is_used)

        s = []
        next_expected = 1

        for x in p_prefix:
            if s and x > s[-1]:
                print(-1)
                return
            s.append(x)
            while s and s[-1] == next_expected:
                s.pop()
                next_expected += 1

        result = list(p_prefix)

        for _ in range(n - k):
            limit = s[-1] - 1 if s else n

            y = query(1, 1, n, 1, limit)

            if y == 0:
                print(-1)
                return

            result.append(y)
            update(1, 1, n, y, 0)

            s.append(y)
            while s and s[-1] == next_expected:
                s.pop()
                next_expected += 1

        while s:
            if s.pop() != next_expected:
                print(-1)
                return
            next_expected += 1

        print(*result)

    except (IOError, IndexError):
        # Handle cases where input is malformed or less than expected
        print(-1)

