    except (IOError, ValueError):
        # Handle empty input for local testing
        return

    w_coords = []
    min_r, max_r = n, -1
    min_c, max_c = m, -1

    for r in range(n):
        for c in range(m):
            if grid[r][c] == 'w':
                w_coords.append((r, c))
                min_r = min(min_r, r)
                max_r = max(max_r, r)
                min_c = min(min_c, c)
                max_c = max(max_c, c)

    if not w_coords:
        for row in grid:
            print("".join(row))
        return

    h_bb = max_r - min_r + 1
    w_bb = max_c - min_c + 1
    size = max(h_bb, w_bb)

    if size > n or size > m:
        print(-1)
        return

    start_r = max(0, max_r - size + 1)
    end_r = min(n - size, min_r)
    start_c = max(0, max_c - size + 1)
    end_c = min(m - size, min_c)

    best_frame = None

    if start_r <= end_r and start_c <= end_c:
        for r_tl in range(start_r, end_r + 1):
            for c_tl in range(start_c, end_c + 1):
                r_br = r_tl + size - 1
                c_br = c_tl + size - 1

                is_valid = True
                for wr, wc in w_coords:
                    on_border = (wr == r_tl or wr == r_br) or (wc == c_tl or wc == c_br)
                    if not on_border:
                        is_valid = False
                        break

                if is_valid:
                    best_frame = (r_tl, c_tl)
                    break 
            if best_frame:
                break

    if not best_frame:
        print(-1)
        return

    r_tl, c_tl = best_frame
    r_br = r_tl + size - 1
    c_br = c_tl + size - 1

    result = [list(row) for row in grid]

    for i in range(r_tl, r_br + 1):
        if result[i][c_tl] == '.':
            result[i][c_tl] = '+'
        if result[i][c_br] == '.':
            result[i][c_br] = '+'

    for j in range(c_tl, c_br + 1):
        if result[r_tl][j] == '.':
            result[r_tl][j] = '+'
        if result[r_br][j] == '.':
            result[r_br][j] = '+'

    for row in result:
        print("".join(row))

