import sys

def solve():
    n = int(sys.stdin.readline())
    s = sys.stdin.readline().strip()
    digits = [int(c) for c in s]

    memo = {}

    def can_partition(index, target_sum):
        if index == n:
            return True
        if index in memo:
            return memo[index]

        current_segment_sum = 0
        for k in range(index, n):
            current_segment_sum += digits[k]
            if current_segment_sum == target_sum:
                if can_partition(k + 1, target_sum):
                    memo[index] = True
                    return True
            elif current_segment_sum > target_sum:
                memo[index] = False
                return False

        memo[index] = False
        return False

    is_lucky = False
    for i in range(1, n):
        target = sum(digits[:i])
        memo.clear()
        if can_partition(i, target):
            is_lucky = True
            break

    if is_lucky:
        print("YES")
    else:
        print("NO")

solve()
