import sys

def main():
    s = sys.stdin.readline().strip()
    k = int(sys.stdin.readline().strip())

    q_marks = s.count('?')
    s_marks = s.count('*')

    letters_count = 0
    for char in s:
        if 'a' <= char <= 'z':
            letters_count += 1

    min_len = letters_count - q_marks - s_marks

    if k < min_len:
        print("Impossible")
        return

    if s_marks == 0 and k > letters_count:
        print("Impossible")
        return

    ans = []

    star_extras = max(0, k - letters_count)

    optionals_to_pick = k - min_len - star_extras

    star_used_for_expansion = False
    i = 0
    while i < len(s):
        char = s[i]

        if not ('a' <= char <= 'z'):
            i += 1
            continue

        is_followed_by_special = (i + 1 < len(s) and s[i+1] in ('?', '*'))

        if not is_followed_by_special:
            ans.append(char)
            i += 1
        else:
            special_char = s[i+1]
            if special_char == '?':
                if optionals_to_pick > 0:
                    ans.append(char)
                    optionals_to_pick -= 1
            elif special_char == '*':
                if star_extras > 0 and not star_used_for_expansion:
                    ans.append(char * (star_extras + 1))
                    star_used_for_expansion = True
                    optionals_to_pick -= 1
                elif optionals_to_pick > 0:
                    ans.append(char)
                    optionals_to_pick -= 1

            i += 2

    final_output = "".join(ans)
    if len(final_output) == k:
        print(final_output)
    else:
        print("Impossible")

if __name__ == "__main__":
    main()
